// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 1 ether);

        address deployer = address(this);

        if (caller != deployer) {
            bool ok;
            try c.setOwner(caller) returns (bool r) { ok = r; } catch { ok = false; }
            vm.assume(ok == true);
        }

        bool result;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool r) { result = r; } catch { result = false; }

        assertTrue(result == true);
    }
}
